def transform(grid):
    """Connect the aligned tips of separate four-point diamond motifs with 1s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    # For each shared row/column, connect consecutive diamond centers.
    for r, c in centers:
        for rr, cc in centers:
            if rr == r and cc > c:
                # Horizontal tips are one cell inward from each center.
                if not any(r2 == r and c < c2 < cc for r2, c2 in centers):
                    for x in range(c + 2, cc - 1):
                        if out[r][x] == 0:
                            out[r][x] = 1
            elif cc == c and rr > r:
                # Vertical tips are one cell inward from each center.
                if not any(c2 == c and r < r2 < rr for r2, c2 in centers):
                    for y in range(r + 2, rr - 1):
                        if out[y][c] == 0:
                            out[y][c] = 1
    return out
